// Writes src/generated/routes.js from routes.json: an import per handler and the route table.
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';

const root = new URL('../', import.meta.url);
const routes = JSON.parse(readFileSync(new URL('routes.json', root), 'utf8'));

const handlers = [...new Set(routes.map((route) => route.handler))].sort();
const lines = [
  '// Generated by tools/generate-routes.js from routes.json. Do not edit: run `npm run generate`.',
  ...handlers.map((name) => `import { ${name} } from '../handlers/${name}.js';`),
  '',
  'export const routes = [',
  ...routes.map(
    (route) => `  { method: '${route.method}', path: '${route.path}', handler: ${route.handler} },`,
  ),
  '];',
  '',
];

mkdirSync(new URL('src/generated/', root), { recursive: true });
writeFileSync(new URL('src/generated/routes.js', root), lines.join('\n'));
console.log(`Wrote src/generated/routes.js with ${routes.length} routes.`);
